CREATE TABLE "agent_samples" (
  "id" TEXT NOT NULL,
  "suite" TEXT NOT NULL,
  "source" TEXT NOT NULL,
  "enabled" BOOLEAN NOT NULL DEFAULT true,
  "currentVersion" INTEGER NOT NULL DEFAULT 1,
  "labels" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "agent_samples_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "agent_sample_versions" (
  "sampleId" TEXT NOT NULL,
  "version" INTEGER NOT NULL,
  "content" JSONB NOT NULL,
  "digest" TEXT NOT NULL,
  "createdById" TEXT,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "changeNote" TEXT NOT NULL DEFAULT '',
  CONSTRAINT "agent_sample_versions_pkey" PRIMARY KEY ("sampleId", "version"),
  CONSTRAINT "agent_sample_versions_sampleId_fkey" FOREIGN KEY ("sampleId") REFERENCES "agent_samples"("id") ON DELETE CASCADE ON UPDATE CASCADE
);

CREATE TABLE "agent_sample_plans" (
  "id" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  "builtin" BOOLEAN NOT NULL DEFAULT false,
  "samples" JSONB NOT NULL,
  "settings" JSONB NOT NULL,
  CONSTRAINT "agent_sample_plans_pkey" PRIMARY KEY ("id")
);

